from collections import defaultdict, deque
comps=defaultdict(list)
seen=set()
for r in range(26):
 for c in range(26):
  v=G[r,c]
  if v not in (0,2) and (r,c) not in seen:
   q=deque([(r,c)]); seen.add((r,c)); cells=[]
   while q:
    p=q.popleft(); cells.append(p)
    for d in ((1,0),(-1,0),(0,1),(0,-1)):
     np_=p[0]+d[0],p[1]+d[1]
     if 0<=np_[0]<26 and 0<=np_[1]<26 and np_[0:2] not in seen and G[np_[0],np_[1]]==v:
      seen.add(np_);q.append(np_)
   comps[v].append(sorted(cells))
for v,cs in comps.items():
 for i,cells in enumerate(cs):
  print('color',v,'comp',i,'n',len(cells),'bbox',min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells),'cells',cells)
print('markers',[(r,c) for r,c in zip(*np.where(G==2))])

for p in [(int(r),int(c)) for r,c in zip(*np.where(G==2))]:
 adj=[]
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  r,c=p[0]+dr,p[1]+dc
  if 0<=r<26 and 0<=c<26 and G[r,c] not in (0,2): adj.append((int(G[r,c]),(r,c)))
 print(p,adj)

# Build piece list from comps and associate each marker with nearby component of its color
pieces=[]
for color,cs in comps.items():
 for i,cells in enumerate(cs):
  core=set(cells)
  ports=set()
  for r,c in [(int(r),int(c)) for r,c in zip(*np.where(G==2))]:
   if any((r+dr,c+dc) in core for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))): ports.add((r,c))
  if ports: 
   minr=min(r for r,c in core); minc=min(c for r,c in core)
   pieces.append({'name':f'{color}{chr(97+i) if len(cs)>1 else ""}','color':int(color),'core':core,'ports':ports,'origin':(minr,minc)})
for p in pieces:
 o=p['origin']; print(p['name'],'core-local',sorted((r-o[0],c-o[1]) for r,c in p['core']),'ports-local',sorted((r-o[0],c-o[1]) for r,c in p['ports']))

from collections import defaultdict
for i,p in enumerate(pieces):
 for q in pieces[i+1:]:
  # t applied to q relative to p local coordinates (q origin shift)
  shifts=defaultdict(int)
  for rp,cp in p['ports']:
   for rq,cq in q['ports']:
    shifts[(rp-rq,cp-cq)]+=1
  cand=[]
  for d,n in shifts.items():
   if n:
    dr,dc=d
    coreov=len(p['core'] & {(r+dr,c+dc) for r,c in q['core']})
    if coreov==0: cand.append((n,d))
  best=sorted(cand,reverse=True)[:4]
  print(p['name'],q['name'],best)

def overlap_candidates(p,q,minov=2):
 shifts=defaultdict(list)
 for a in p['ports']:
  for b in q['ports']:
   shifts[(a[0]-b[0],a[1]-b[1])].append((a,b))
 out=[]
 for d,pairs in shifts.items():
  # dedupe p marker coordinates
  n=len(set(a for a,b in pairs))
  if n>=minov:
   dr,dc=d
   coreov=len(p['core'] & {(r+dr,c+dc) for r,c in q['core']})
   # also count placements where ports of either overlay other's core? not invalid? only core-core
   out.append((d,n,coreov,sorted(set(pairs))))
 return sorted(out,key=lambda x:(-x[1],x[0]))
for i,p in enumerate(pieces):
 for q in pieces[i+1:]:
  c=overlap_candidates(p,q)
  if c: print('\n',p['name'],q['name'],[(d,n,co) for d,n,co,_ in c])

for p,q in [(pieces[3],pieces[5]),(pieces[0],pieces[2]),(pieces[2],pieces[5]),(pieces[2],pieces[6]),(pieces[3],pieces[6]),(pieces[4],pieces[6])]:
 print('\n',p['name'],q['name'])
 for d,n,co,pairs in overlap_candidates(p,q):
  print('d',d,'n',n,'coreov',co,'pairs',pairs)

for p,q in [(pieces[0],pieces[5]),(pieces[0],pieces[2]),(pieces[2],pieces[5]),(pieces[3],pieces[5]),(pieces[2],pieces[6]),(pieces[1],pieces[6])]:
 print('\n',p['name'],q['name'])
 for d,n,co,pairs in overlap_candidates(p,q):
  print('d',d,'n',n,'coreov',co,'pairs',pairs)

