 dr,dc=trans[p['name']]
 cells={ (r+dr,c+dc) for r,c in p['core']}
 ports={ (r+dr,c+dc) for r,c in p['ports']}
 print(p['name'],'shift',(dr,dc),'core bbox', (min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells)), 'ports', sorted(ports))
 placements.append((p,cells,ports))
 for r,c in cells:
  if not (0<=r<26 and 0<=c<26): print('OOB core',p['name'],r,c)
  if out[r,c] not in (0,p['color']): print('core collision',p['name'],r,c,out[r,c])
  out[r,c]=p['color']
for p,cells,ports in placements:
 for r,c in ports:
  if not (0<=r<26 and 0<=c<26): print('OOB port',p['name'],r,c)
  if out[r,c] not in (0,2): print('port-core conflict',p['name'],r,c,out[r,c])
  out[r,c]=2
